package GeneratedModel {
  private import ScalarValues::*;
  part def Controller {
    in attribute io_0 : Real;
    in attribute io_1 : Real;
    in attribute io_2 : Boolean;
    attribute alarmActive : Boolean := false;
    attribute ledState : Boolean := false;
    attribute beepState : Boolean := false;
    perform action tick {
      first start;
      then assign alarmActive := ((((io_0) <= (300.0))) and (((io_2) and (((io_1) <= (20.0))))));
      then if alarmActive {
        first start;
        then assign ledState := (not ledState);
        then assign beepState := (not beepState);
      }
    }
    out attribute io_3 : Boolean = ledState and alarmActive;
    out attribute io_4 : Integer = (if alarmActive and beepState ? 2000 else 0);
    out attribute serial_0_trigger : Boolean = alarmActive;
    out attribute serial_0_value_0 : Boolean = alarmActive;
  }
  part system : Controller;
}
